-- ============================================================================
-- 0012_market_intelligence.sql
--
-- Mengisi Layer 4 & 5 (Market Demand dan Salary Intelligence) untuk seluruh
-- 477 profesi aktif, plus ketahanan terhadap otomasi.
--
-- SEMUA ANGKA DI FILE INI HASIL ESTIMASI MODEL, BUKAN DATA SURVEI.
--
-- Ditulis di sini besar-besar karena angkanya akan tampil ke pengguna dan
-- terlihat persis seperti data sungguhan. Tiap baris membawa source =
-- 'estimasi_model' dan confidence-nya sendiri; view `career_market` di bawah
-- ikut mengembalikan kolom itu supaya UI bisa menampilkan label "estimasi".
--
-- Kenapa model, bukan angka per profesi: 477 angka yang dikarang satu per satu
-- tidak bisa diperiksa, tidak konsisten antar profesi, dan tidak bisa
-- diperbaiki serentak. Model punya parameter yang tertulis, jadi kalau ada yang
-- tidak setuju dengan premi sektor teknologi, satu angka diubah dan seluruh
-- tabel ikut menyesuaikan.
--
-- Rumusnya (parameter lengkap di supabase/roadmap/market_model.py):
--
--   gaji      = UMP nasional x pengali jenjang x pengali Job Zone x premi industri
--               UMP 3,100,000 (2025). Ganti satu angka ini tiap kenaikan UMP.
--   demand    = luas rumpun (maks 30) + pertumbuhan industri (maks 35)
--               + keterjangkauan jenjang (6-30)
--   growth    = pertumbuhan tahunan industri yang ditautkan, ambil yang tertinggi
--   ai_res    = rata-rata ketahanan Activity DNA-nya, disesuaikan Skill DNA.
--               Ini satu-satunya yang benar-benar diturunkan dari data profesi,
--               bukan dari asumsi sektor: aktivitas yang menuntut kehadiran
--               fisik dan penilaian situasional sulit digantikan, yang mengolah
--               informasi menurut aturan tetap paling mudah.
--
-- Yang harus diganti kalau data sungguhan datang: seluruh isi tabel
-- career_market. Strukturnya tidak perlu berubah — cukup ganti source dan
-- confidence-nya.
--
-- Jalankan setelah 0011. Aman diulang.
-- ============================================================================

begin;

create table if not exists public.career_market (
  career_id      integer primary key references public.careers(id) on delete cascade,
  salary_min     bigint,
  salary_max     bigint,
  salary_period  text    not null default 'bulan',
  currency       text    not null default 'IDR',
  demand_score   smallint,
  growth_pct     numeric(5,1),
  ai_resilience  smallint,
  source         text    not null,
  confidence     text    not null,
  as_of_year     smallint not null,
  note           text,
  updated_at     timestamptz not null default now(),
  constraint chk_market_scores check (
    (demand_score  is null or demand_score  between 0 and 100) and
    (ai_resilience is null or ai_resilience between 0 and 100)),
  constraint chk_market_salary check (
    salary_min is null or salary_max is null or salary_min <= salary_max),
  constraint chk_market_conf check (confidence in ('high','medium','low','none'))
);

comment on table public.career_market is
  'Layer 4-5. Isi sekarang seluruhnya estimasi model, bukan survei. Periksa kolom source sebelum menampilkan angkanya sebagai fakta.';
comment on column public.career_market.ai_resilience is
  '0-100. Diturunkan dari komposisi Activity DNA profesi: makin tinggi, makin sulit digantikan otomasi. Satu-satunya kolom di tabel ini yang tidak bergantung asumsi sektor.';
comment on column public.career_market.demand_score is
  '0-100. Gabungan luas rumpun, pertumbuhan industri, dan keterjangkauan jenjang. Bukan jumlah lowongan.';

