on conflict (career_id) do update set
  salary_min=excluded.salary_min, salary_max=excluded.salary_max,
  demand_score=excluded.demand_score, growth_pct=excluded.growth_pct,
  ai_resilience=excluded.ai_resilience, source=excluded.source,
  confidence=excluded.confidence, as_of_year=excluded.as_of_year,
  note=excluded.note, updated_at=now();

-- Kolom gaji lama di tabel careers ikut diisi supaya kode yang sudah membacanya
-- tidak perlu diubah, lengkap dengan penanda sumbernya.
update public.careers c set
  salary_min = m.salary_min,
  salary_max = m.salary_max,
  salary_source = 'estimasi_model',
  salary_confidence = 'low'
from public.career_market m
where m.career_id = c.id;

-- Semua profesi aktif wajib punya baris pasar. Kalau ada yang lolos, angka
-- kosong itu akan tampil sebagai "-" di UI tanpa ada yang tahu kenapa.
do $$
declare n int;
begin
  select count(*) into n from public.careers c
  where c.is_active and not exists (select 1 from public.career_market m where m.career_id=c.id);
  if n > 0 then raise exception '% profesi aktif belum punya data pasar', n; end if;
end $$;

create or replace view public.career_market_view
with (security_invoker = true) as
select c.id as career_id, c.career_name, c.family_code,
       m.salary_min, m.salary_max, m.salary_period, m.currency,
       m.demand_score, m.growth_pct, m.ai_resilience,
       m.source, m.confidence, m.as_of_year,
       -- Label siap pakai supaya tiap layar tidak menuliskan ambangnya sendiri.
       case when m.demand_score >= 75 then 'Tinggi'
            when m.demand_score >= 50 then 'Sedang' else 'Rendah' end as demand_label,
       case when m.ai_resilience >= 70 then 'Tahan'
            when m.ai_resilience >= 50 then 'Cukup tahan' else 'Rentan' end as ai_label,
       (m.source = 'estimasi_model') as is_estimasi
from public.careers c
join public.career_market m on m.career_id = c.id
where c.is_active;

comment on view public.career_market_view is
  'Data pasar siap tampil. Kolom is_estimasi WAJIB dipakai UI untuk menandai angka yang belum berasal dari survei.';

alter table public.career_market enable row level security;
drop policy if exists career_market_read_all on public.career_market;
create policy career_market_read_all on public.career_market
  for select to anon, authenticated using (true);

commit;

